from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class HATEOASLink(SchemaObject):
    rel = SchemaField(name='rel', optional=True)
    href = SchemaField(name='href', not_null=True)

    def __init__(self, rel, href):
        self.rel = rel
        self.href = href

        super(HATEOASLink, self).__init__()


class DetaildStatus(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    status = SchemaField(name='status', not_null=True)

    def __init__(self, id, status):
        self.id = id
        self.status = status

        super(DetaildStatus, self).__init__()


class LockUnlockCellsResponseASMV1(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    links = SchemaField(name='links', many=True, klass=HATEOASLink, optional=True)
    status = SchemaField(name='status', not_null=True)
    detailed_statuses = SchemaField(name='detailedStatuses', many=True, optional=True, klass=DetaildStatus)
    error_message = SchemaField(name='errorMessage', optional=True)

    def __init__(self, id, links, status, detailed_statuses, error_message):
        self.id = id
        self.links = links
        self.status = status
        self.detailed_statuses = detailed_statuses
        self.error_message = error_message

        super(LockUnlockCellsResponseASMV1, self).__init__()
